<?php
namespace App\Jobs;use App\Models\{EventFaceIndexRun,MediaAsset};use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Queue\Middleware\WithoutOverlapping;
class RunEventFaceIndex implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function __construct(public int$runId){$this->onQueue('media-default');}public function middleware():array{return[(new WithoutOverlapping('event-face-index-'.$this->runId))->expireAfter(600)->dontRelease()];}public function handle():void{$run=EventFaceIndexRun::findOrFail($this->runId);$run->update(['state'=>'processing']);$assets=MediaAsset::where('group_id',$run->group_id)->where('id','>',$run->cursor)->orderBy('id')->limit(100)->get();foreach($assets as$a){IndexFaceAsset::dispatch($a->id);$run->increment('completed');$run->update(['cursor'=>$a->id]);}$remaining=MediaAsset::where('group_id',$run->group_id)->where('id','>',$run->cursor)->exists();$run->update(['state'=>$remaining?'queued':'completed']);if($remaining)self::dispatch($run->id);}}
